-- Independent drama projects and immutable source snapshots. Manual migration.
SET search_path TO new_design, public;
CREATE TABLE drama_projects(id uuid PRIMARY KEY,title text NOT NULL,source_type text NOT NULL CHECK(source_type IN('novel','original','text')),track text NOT NULL DEFAULT 'auto',target_episodes integer NOT NULL CHECK(target_episodes BETWEEN 1 AND 200),episode_duration_sec integer NOT NULL CHECK(episode_duration_sec BETWEEN 30 AND 3600),revision integer NOT NULL DEFAULT 0,adopted_source_version_id uuid,create_request_key uuid NOT NULL UNIQUE,create_input_hash char(64) NOT NULL CHECK(create_input_hash ~ '^[a-f0-9]{64}$'),status text NOT NULL DEFAULT 'draft' CHECK(status='draft'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drama_source_versions(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES drama_projects(id),version integer NOT NULL CHECK(version>0),source_type text NOT NULL,source_book_id uuid,source_book_name text,content text NOT NULL,content_hash char(64) NOT NULL CHECK(content_hash ~ '^[a-f0-9]{64}$'),manifest jsonb NOT NULL CHECK(jsonb_typeof(manifest)='object'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version),UNIQUE(project_id,id));
ALTER TABLE drama_projects ADD CONSTRAINT drama_project_source_fk FOREIGN KEY(id,adopted_source_version_id) REFERENCES drama_source_versions(project_id,id);
CREATE FUNCTION guard_drama_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'drama history is immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER drama_source_versions_immutable BEFORE UPDATE OR DELETE ON drama_source_versions FOR EACH ROW EXECUTE FUNCTION guard_drama_history();
